/* ClipCast Custom Styles */

:root {
  --primary: #1868DB;
  --primary-dark: #1457b8;
  --accent: #FF613D;
  --accent-light: #ff7a5c;
  --dark: #292A2E;
  --dark-light: #3a3b40;
  --gray-50: #f8fafc;
  --gray-100: #f1f5f9;
  --gray-200: #e2e8f0;
  --gray-300: #cbd5e1;
  --gray-400: #94a3b8;
  --gray-500: #64748b;
  --gray-600: #475569;
  --gray-700: #334155;
  --gray-800: #1e293b;
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
}

* {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  color: var(--dark);
  background: #fff;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Typography */
.font-display {
  font-family: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
}

/* Gradients */
.gradient-primary {
  background: linear-gradient(135deg, #1868DB 0%, #4f8ef7 100%);
}

.gradient-accent {
  background: linear-gradient(135deg, #FF613D 0%, #ff8a70 100%);
}

.gradient-hero {
  background: linear-gradient(180deg, #f0f7ff 0%, #ffffff 100%);
}

.gradient-purple {
  background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 50%, #a855f7 100%);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.9375rem;
  transition: all 0.2s ease;
  cursor: pointer;
  border: none;
  outline: none;
}

.btn:focus-visible {
  ring: 2px;
  ring-offset: 2px;
  ring-color: var(--primary);
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--accent);
  color: white;
}

.btn-accent:hover {
  background: #e55730;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-white {
  background: white;
  color: var(--primary);
}

.btn-white:hover {
  background: var(--gray-50);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--dark);
  border: 1.5px solid var(--gray-300);
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(24, 104, 219, 0.04);
}

.btn-ghost {
  background: transparent;
  color: var(--gray-600);
}

.btn-ghost:hover {
  color: var(--dark);
  background: var(--gray-100);
}

/* Cards */
.card {
  background: white;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  transition: all 0.25s ease;
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-color: var(--gray-300);
}

.card-featured {
  border: 2px solid var(--primary);
  position: relative;
}

.card-featured::before {
  content: attr(data-badge);
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.875rem;
  border-radius: 9999px;
  white-space: nowrap;
}

/* Navigation */
.nav-link {
  color: var(--gray-600);
  font-weight: 500;
  font-size: 0.9375rem;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius);
  transition: all 0.15s ease;
}

.nav-link:hover {
  color: var(--dark);
  background: var(--gray-100);
}

/* Sections */
.section {
  padding: 5rem 1rem;
}

@media (min-width: 768px) {
  .section {
    padding: 6rem 1.5rem;
  }
}

@media (min-width: 1024px) {
  .section {
    padding: 7rem 2rem;
  }
}

.section-alt {
  background: var(--gray-50);
}

/* Animations */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes pulse-soft {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.animate-fade-in-up {
  animation: fadeInUp 0.5s ease-out forwards;
}

.animate-fade-in {
  animation: fadeIn 0.4s ease-out forwards;
}

.animate-slide-in-right {
  animation: slideInRight 0.5s ease-out forwards;
}

/* Stagger delays */
.delay-100 { animation-delay: 100ms; }
.delay-200 { animation-delay: 200ms; }
.delay-300 { animation-delay: 300ms; }
.delay-400 { animation-delay: 400ms; }
.delay-500 { animation-delay: 500ms; }

/* Pricing toggle */
.toggle-switch {
  position: relative;
  display: inline-flex;
  background: var(--gray-200);
  border-radius: 9999px;
  padding: 0.25rem;
  cursor: pointer;
}

.toggle-switch .toggle-option {
  position: relative;
  z-index: 1;
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 9999px;
  transition: all 0.2s ease;
  color: var(--gray-500);
  cursor: pointer;
  border: none;
  background: transparent;
}

.toggle-switch .toggle-option.active {
  color: var(--dark);
  background: white;
  box-shadow: var(--shadow-sm);
}

/* Range slider */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: var(--gray-200);
  border-radius: 3px;
  outline: none;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: all 0.15s ease;
}

input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.1);
}

input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  border: none;
  box-shadow: var(--shadow-md);
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.25rem 0;
  font-weight: 600;
  font-size: 1.0625rem;
  color: var(--dark);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: color 0.15s ease;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
  color: var(--gray-600);
  line-height: 1.7;
}

.faq-answer.open {
  max-height: 500px;
  padding-bottom: 1.25rem;
}

.faq-icon {
  transition: transform 0.3s ease;
  flex-shrink: 0;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

/* Cookie banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: white;
  border-top: 1px solid var(--gray-200);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.08);
  padding: 1.25rem;
  transform: translateY(100%);
  transition: transform 0.4s ease;
}

.cookie-banner.show {
  transform: translateY(0);
}

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  background: rgba(0,0,0,0.4);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.modal-overlay.open {
  opacity: 1;
  pointer-events: auto;
}

.modal-content {
  background: white;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  max-width: 480px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
  transform: scale(0.95);
  transition: transform 0.3s ease;
}

.modal-overlay.open .modal-content {
  transform: scale(1);
}

/* Social auth buttons */
.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  width: 100%;
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  border: 1.5px solid var(--gray-200);
  background: white;
  color: var(--dark);
  font-weight: 500;
  font-size: 0.9375rem;
  cursor: pointer;
  transition: all 0.15s ease;
}

.social-btn:hover {
  border-color: var(--gray-300);
  background: var(--gray-50);
}

/* Form inputs */
.form-input {
  width: 100%;
  padding: 0.875rem 1rem;
  border-radius: var(--radius);
  border: 1.5px solid var(--gray-200);
  background: white;
  color: var(--dark);
  font-size: 0.9375rem;
  transition: all 0.15s ease;
  outline: none;
}

.form-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(24, 104, 219, 0.1);
}

.form-input::placeholder {
  color: var(--gray-400);
}

/* Divider */
.divider {
  display: flex;
  align-items: center;
  gap: 1rem;
  color: var(--gray-400);
  font-size: 0.875rem;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

/* Comparison table */
.comparison-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.comparison-table th,
.comparison-table td {
  padding: 1rem 1.25rem;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.comparison-table th {
  font-weight: 600;
  color: var(--dark);
  background: var(--gray-50);
}

.comparison-table td {
  color: var(--gray-600);
}

.comparison-table .check {
  color: #10b981;
}

.comparison-table .dash {
  color: var(--gray-300);
}

/* Testimonial card */
.testimonial-card {
  background: white;
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  border: 1px solid var(--gray-200);
}

/* Stats */
.stat-number {
  font-size: 3rem;
  font-weight: 800;
  line-height: 1;
  background: linear-gradient(135deg, var(--primary) 0%, #4f8ef7 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Use case card */
.use-case-card {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-lg);
  background: white;
  border: 1px solid var(--gray-200);
  padding: 2rem;
  transition: all 0.25s ease;
}

.use-case-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
  border-color: var(--gray-300);
}

/* Feature icon wrapper */
.feature-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(24,104,219,0.1) 0%, rgba(79,142,247,0.1) 100%);
  color: var(--primary);
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: var(--gray-100);
}

::-webkit-scrollbar-thumb {
  background: var(--gray-300);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--gray-400);
}

/* Mobile menu */
.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 40;
  background: white;
  padding: 5rem 1.5rem 1.5rem;
  flex-direction: column;
  gap: 0.5rem;
}

.mobile-menu.open {
  display: flex;
}

/* Plan card pricing */
.plan-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
  line-height: 1;
}

.plan-price .period {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-500);
}

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 700;
}

.badge-primary {
  background: rgba(24, 104, 219, 0.1);
  color: var(--primary);
}

.badge-accent {
  background: rgba(255, 97, 61, 0.1);
  color: var(--accent);
}

/* Blog card */
.blog-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: white;
  border: 1px solid var(--gray-200);
  transition: all 0.25s ease;
}

.blog-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.blog-card img {
  width: 100%;
  height: 200px;
  object-fit: cover;
}

/* Integration logo placeholder */
.integration-logo {
  width: 64px;
  height: 64px;
  border-radius: var(--radius);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  color: var(--gray-500);
  font-size: 0.75rem;
  border: 1px solid var(--gray-200);
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

@media (min-width: 768px) {
  .container {
    padding: 0 1.5rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 2rem;
  }
}

// ClipCast Main JavaScript

(function() {
  'use strict';

  // Initialize Lucide icons
  document.addEventListener('DOMContentLoaded', function() {
    if (typeof lucide !== 'undefined') {
      lucide.createIcons();
    }

    initMobileMenu();
    initPricingToggle();
    initTeamSizeSlider();
    initFAQAccordion();
    initCookieConsent();
    initScrollAnimations();
    initComparisonTableExpand();
  });

  // Mobile menu
  function initMobileMenu() {
    const menuBtn = document.getElementById('mobile-menu-btn');
    const closeBtn = document.getElementById('mobile-menu-close');
    const mobileMenu = document.getElementById('mobile-menu');

    if (menuBtn && mobileMenu) {
      menuBtn.addEventListener('click', function() {
        mobileMenu.classList.add('open');
        document.body.style.overflow = 'hidden';
      });
    }

    if (closeBtn && mobileMenu) {
      closeBtn.addEventListener('click', function() {
        mobileMenu.classList.remove('open');
        document.body.style.overflow = '';
      });
    }
  }

  // Pricing billing toggle
  function initPricingToggle() {
    const toggleMonthly = document.getElementById('toggle-monthly');
    const toggleAnnual = document.getElementById('toggle-annual');
    const saveBadge = document.getElementById('save-badge');
    const priceBusiness = document.getElementById('price-business');
    const priceBusinessAI = document.getElementById('price-business-ai');
    const periodLabels = document.querySelectorAll('.price-period');

    if (!toggleMonthly || !toggleAnnual) return;

    function setMonthly() {
      toggleMonthly.classList.add('active');
      toggleAnnual.classList.remove('active');
      if (saveBadge) saveBadge.style.display = 'none';
      if (priceBusiness) priceBusiness.textContent = '$18';
      if (priceBusinessAI) priceBusinessAI.textContent = '$24';
      periodLabels.forEach(function(el) {
        el.textContent = '/user/mo';
      });
    }

    function setAnnual() {
      toggleAnnual.classList.add('active');
      toggleMonthly.classList.remove('active');
      if (saveBadge) saveBadge.style.display = 'inline-flex';
      // Annual: 17% off
      if (priceBusiness) priceBusiness.textContent = '$15';
      if (priceBusinessAI) priceBusinessAI.textContent = '$20';
      periodLabels.forEach(function(el) {
        el.textContent = '/user/mo billed annually';
      });
    }

    toggleMonthly.addEventListener('click', setMonthly);
    toggleAnnual.addEventListener('click', setAnnual);
  }

  // Team size slider
  function initTeamSizeSlider() {
    const slider = document.getElementById('team-size-slider');
    const display = document.getElementById('team-size-display');
    const recommendation = document.getElementById('plan-recommendation');

    if (!slider || !display) return;

    function updateSlider() {
      const val = parseInt(slider.value);
      display.textContent = val + (val === 100 ? '+' : '');

      if (recommendation) {
        let rec = '';
        if (val <= 5) {
          rec = 'Starter is perfect for your team size.';
        } else if (val <= 20) {
          rec = 'Business plan is recommended for your team.';
        } else if (val <= 50) {
          rec = 'Business + AI will supercharge your workflow.';
        } else {
          rec = 'Enterprise is built for teams your size.';
        }
        recommendation.textContent = rec;
      }
    }

    slider.addEventListener('input', updateSlider);
    updateSlider();
  }

  // FAQ Accordion
  function initFAQAccordion() {
    const faqItems = document.querySelectorAll('.faq-item');

    faqItems.forEach(function(item) {
      const question = item.querySelector('.faq-question');
      const answer = item.querySelector('.faq-answer');

      if (!question || !answer) return;

      question.addEventListener('click', function() {
        const isOpen = item.classList.contains('open');

        // Close all others (optional accordion behavior)
        faqItems.forEach(function(other) {
          if (other !== item) {
            other.classList.remove('open');
            const otherAnswer = other.querySelector('.faq-answer');
            if (otherAnswer) otherAnswer.classList.remove('open');
          }
        });

        if (isOpen) {
          item.classList.remove('open');
          answer.classList.remove('open');
        } else {
          item.classList.add('open');
          answer.classList.add('open');
        }
      });
    });
  }

  // Cookie consent
  function initCookieConsent() {
    const banner = document.getElementById('cookie-banner');
    const acceptBtn = document.getElementById('cookie-accept');
    const rejectBtn = document.getElementById('cookie-reject');
    const manageBtn = document.getElementById('cookie-manage');
    const modal = document.getElementById('cookie-modal');
    const modalClose = document.getElementById('cookie-modal-close');
    const modalSave = document.getElementById('cookie-modal-save');

    // Check if already consented
    const consent = localStorage.getItem('cookie-consent');
    if (!consent && banner) {
      setTimeout(function() {
        banner.classList.add('show');
      }, 800);
    }

    if (acceptBtn && banner) {
      acceptBtn.addEventListener('click', function() {
        localStorage.setItem('cookie-consent', 'accepted');
        banner.classList.remove('show');
      });
    }

    if (rejectBtn && banner) {
      rejectBtn.addEventListener('click', function() {
        localStorage.setItem('cookie-consent', 'rejected');
        banner.classList.remove('show');
      });
    }

    if (manageBtn && modal) {
      manageBtn.addEventListener('click', function() {
        modal.classList.add('open');
      });
    }

    if (modalClose && modal) {
      modalClose.addEventListener('click', function() {
        modal.classList.remove('open');
      });
    }

    if (modalSave && modal) {
      modalSave.addEventListener('click', function() {
        localStorage.setItem('cookie-consent', 'custom');
        modal.classList.remove('open');
        if (banner) banner.classList.remove('show');
      });
    }

    if (modal) {
      modal.addEventListener('click', function(e) {
        if (e.target === modal) {
          modal.classList.remove('open');
        }
      });
    }
  }

  // Scroll animations (simple intersection observer)
  function initScrollAnimations() {
    const animatedElements = document.querySelectorAll('[data-animate]');
    if (!animatedElements.length) return;

    const observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          const el = entry.target;
          const animation = el.getAttribute('data-animate');
          const delay = el.getAttribute('data-delay') || '0';
          el.style.animationDelay = delay + 'ms';
          el.classList.add('animate-' + animation);
          el.style.opacity = '1';
          observer.unobserve(el);
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });

    animatedElements.forEach(function(el) {
      el.style.opacity = '0';
      observer.observe(el);
    });
  }

  // Comparison table expand
  function initComparisonTableExpand() {
    const expandBtn = document.getElementById('comparison-expand-btn');
    const expandRows = document.querySelectorAll('.comparison-expandable');

    if (!expandBtn || !expandRows.length) return;

    let expanded = false;
    expandBtn.addEventListener('click', function() {
      expanded = !expanded;
      expandRows.forEach(function(row) {
        row.style.display = expanded ? 'table-row' : 'none';
      });
      expandBtn.textContent = expanded ? 'Show fewer features' : 'See all features';
    });
  }
})();

