    # Check for relative links
    links = re.findall(r'href=[\"\']([^\"\']+)[\"\']', content)
    for link in links:
        if link.startswith('http') or link.startswith('#') or link.startswith('mailto'):
            continue
        if link not in ['index.html', 'enterprise.html', 'pricing.html', 'login.html', 'signup.html', 'styles.css', 'flowbite.min.css', 'main.js', 'lucide.min.js', 'tailwind.js']:
            issues.append(f'{f}: suspicious link {link}')

    # Check for required nav links on main pages
